<?php require_once "config.php"; delivery_required();
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_POST['id'];$status=$_POST['status'];$allowed=['Assigned','On the Way','Delivered'];if(in_array($status,$allowed,true)){ $st=$conn->prepare("UPDATE orders SET status=? WHERE id=? AND delivery_person_id=?");$st->bind_param("sii",$status,$id,$_SESSION['delivery_id']);$st->execute();}}
$st=$conn->prepare("SELECT * FROM orders WHERE delivery_person_id=? AND delivery_method='delivery' ORDER BY created_at DESC");$st->bind_param("i",$_SESSION['delivery_id']);$st->execute();$orders=$st->get_result();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Delivery Dashboard</title><link rel="icon" href="favicon.ico" sizes="any"><link rel="icon" type="image/png" href="logo-192.png"><link rel="apple-touch-icon" href="apple-touch-icon.png"><link rel="stylesheet" href="style.css"></head><body><header class="admin-header"><div class="container nav"><strong>Delivery · <?= e($_SESSION['delivery_name']) ?></strong><a href="delivery_logout.php">Logout</a></div></header><main class="container"><div class="page-title"><h1>My orders</h1></div><div class="delivery-cards"><?php while($o=$orders->fetch_assoc()): ?><div class="admin-card"><div class="track-top"><strong><?= e($o['order_number']) ?></strong><span class="status"><?= e($o['status']) ?></span></div><p><strong><?= e($o['customer_name']) ?></strong><br><?= e($o['phone']) ?><br><?= e($o['delivery_location']) ?></p><p>Total: <strong>TZS <?= number_format($o['total_amount']) ?></strong></p><form method="post"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><select name="status"><option>Assigned</option><option>On the Way</option><option>Delivered</option></select><button class="btn btn-small">Update</button></form></div><?php endwhile; ?></div></main></body></html>